export const CEA_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/cea-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getCeaStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(CEA_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
